import XCTest

final class LaunchTests: XCTestCase {
    /// `build/fixtures/` in the repo (generated by scripts/dev/make-fixtures.sh); the simulator
    /// app can read host paths.
    static let fixtures = URL(filePath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .appending(path: "build/fixtures")

    @MainActor
    func testLaunchShowsEmptyLibrary() {
        let app = XCUIApplication()
        app.launchArguments = ["--reset", "-AppleLanguages", "(en)"]
        app.launch()
        XCTAssertTrue(app.staticTexts["No recordings yet"].waitForExistence(timeout: 10))
        XCTAssertTrue(app.buttons["importButton"].exists)
    }

    /// "Open in" with a video (same path as `--import`): the detail screen opens on the imported
    /// audio, it plays, and the recording is in the list.
    @MainActor
    func testImportVideoOpensDetail() throws {
        let video = Self.fixtures.appending(path: "import_en.mp4")
        try XCTSkipUnless(FileManager.default.fileExists(atPath: video.path), "run scripts/dev/make-fixtures.sh")
        let app = XCUIApplication()
        app.launchArguments = ["--reset", "--import", video.path, "-AppleLanguages", "(en)"]
        app.launch()
        let title = app.staticTexts["detailTitle"]
        XCTAssertTrue(title.waitForExistence(timeout: 15))
        XCTAssertEqual(title.label, "import_en")
        app.buttons["playButton"].tap()
        let moved = NSPredicate(format: "label != '0:00'")
        expectation(for: moved, evaluatedWith: app.staticTexts["position"])
        waitForExpectations(timeout: 5)
        app.buttons["playButton"].tap()
        app.navigationBars.buttons.element(boundBy: 0).tap()
        XCTAssertTrue(app.staticTexts["import_en"].waitForExistence(timeout: 5))
    }

    /// The speed menu: choosing 2× changes the label and playback runs at double speed.
    @MainActor
    func testSpeedMenu() throws {
        let audio = Self.fixtures.appending(path: "import_nl.m4a")
        try XCTSkipUnless(FileManager.default.fileExists(atPath: audio.path), "run scripts/dev/make-fixtures.sh")
        let app = XCUIApplication()
        app.launchArguments = ["--reset", "--import", audio.path, "-AppleLanguages", "(en)"]
        app.launch()
        let speed = app.buttons["speedMenu"]
        XCTAssertTrue(speed.waitForExistence(timeout: 15))
        speed.tap()
        let double = app.buttons["2×"]
        XCTAssertTrue(double.waitForExistence(timeout: 5))
        double.tap()
        XCTAssertEqual(speed.value as? String, "2×")
        app.buttons["playButton"].tap()
        sleep(3)
        app.buttons["playButton"].tap()
        let position = app.staticTexts["position"].label  // m:ss
        let seconds = Int(position.split(separator: ":").last ?? "0") ?? 0
        XCTAssertGreaterThanOrEqual(seconds, 5, "position \(position) after 3 s at 2×")
    }

    /// Transcribe from the detail screen: progress appears, then the transcript; tapping a
    /// sentence moves the position; the library search finds the recording by a transcript word.
    @MainActor
    func testTranscribeFromDetail() throws {
        let audio = Self.fixtures.appending(path: "nl_dialogue.wav")
        try XCTSkipUnless(FileManager.default.fileExists(atPath: audio.path), "run scripts/dev/make-fixtures.sh")
        let app = XCUIApplication()
        app.launchArguments = ["--reset", "--import", audio.path, "-AppleLanguages", "(en)"]
        app.launch()
        let transcribe = app.buttons["transcribeButton"]
        XCTAssertTrue(transcribe.waitForExistence(timeout: 15))
        transcribe.tap()
        XCTAssertTrue(app.descendants(matching: .any)["transcriptionProgress"].waitForExistence(timeout: 5))
        let sentence = app.links.matching(NSPredicate(format: "label CONTAINS[c] 'begroting'")).firstMatch
        XCTAssertTrue(sentence.waitForExistence(timeout: 120))
        XCTAssertFalse(app.descendants(matching: .any)["transcriptionProgress"].exists)
        XCTAssertEqual(app.staticTexts["position"].label, "0:00")
        sentence.tap()
        // "Zullen we dan ook meteen de begroting…" starts at about 0:19.
        expectation(for: NSPredicate(format: "label BEGINSWITH '0:1' OR label BEGINSWITH '0:2'"), evaluatedWith: app.staticTexts["position"])
        waitForExpectations(timeout: 5)

        app.navigationBars.buttons.element(boundBy: 0).tap()
        // The system's search field under the large title.
        let search = app.searchFields.firstMatch
        XCTAssertTrue(search.waitForExistence(timeout: 5))
        search.tap()
        app.typeText("kwartaal")
        XCTAssertTrue(app.staticTexts["nl_dialogue"].waitForExistence(timeout: 5))
        search.typeText("xyz")
        XCTAssertFalse(app.staticTexts["nl_dialogue"].waitForExistence(timeout: 2))
    }

    /// Without Apple Intelligence the summary tab does not exist (DEBUG `--fm-unavailable`).
    @MainActor
    func testSummaryTabHiddenWhenUnavailable() throws {
        let audio = Self.fixtures.appending(path: "nl_dialogue.wav")
        try XCTSkipUnless(FileManager.default.fileExists(atPath: audio.path), "run scripts/dev/make-fixtures.sh")
        let app = XCUIApplication()
        app.launchArguments = ["--reset", "--fm-unavailable", "--transcribe", audio.path, "-AppleLanguages", "(en)"]
        app.launch()
        let sentence = app.links.matching(NSPredicate(format: "label CONTAINS[c] 'begroting'")).firstMatch
        XCTAssertTrue(sentence.waitForExistence(timeout: 120))
        XCTAssertFalse(app.descendants(matching: .any)["detailTabs"].exists)
        XCTAssertFalse(app.buttons["Summary"].exists)
        app.buttons["shareMenu"].tap()
        XCTAssertTrue(app.buttons["Transcript as text"].waitForExistence(timeout: 3))
        XCTAssertFalse(app.buttons["Summary"].exists)
    }

    /// With Apple Intelligence: the Summary tab makes a summary with the template's headings,
    /// switching back shows the transcript. Skipped where the model is not available.
    @MainActor
    func testSummaryTab() throws {
        let audio = Self.fixtures.appending(path: "nl_dialogue.wav")
        try XCTSkipUnless(FileManager.default.fileExists(atPath: audio.path), "run scripts/dev/make-fixtures.sh")
        let app = XCUIApplication()
        app.launchArguments = ["--reset", "--transcribe", audio.path, "-AppleLanguages", "(en)"]
        app.launch()
        let sentence = app.links.matching(NSPredicate(format: "label CONTAINS[c] 'begroting'")).firstMatch
        XCTAssertTrue(sentence.waitForExistence(timeout: 120))
        try XCTSkipUnless(app.descendants(matching: .any)["detailTabs"].waitForExistence(timeout: 2),
                          "Apple Intelligence not available in this simulator")
        app.buttons["Summary"].tap()
        let summarize = app.buttons["summarizeButton"]
        XCTAssertTrue(summarize.waitForExistence(timeout: 5))
        summarize.tap()
        // The button opens the templates; the meeting template has the headings checked below.
        let meeting = app.buttons["Meeting"]
        XCTAssertTrue(meeting.waitForExistence(timeout: 5))
        meeting.tap()
        XCTAssertTrue(app.staticTexts["Action items"].waitForExistence(timeout: 120))
        XCTAssertTrue(app.staticTexts["Decisions"].exists)
        XCTAssertFalse(summarize.exists)
        app.buttons["Transcript"].tap()
        XCTAssertTrue(sentence.waitForExistence(timeout: 5))
        app.buttons["shareMenu"].tap()
        XCTAssertTrue(app.buttons["Summary"].waitForExistence(timeout: 3))
    }

    /// Record with the fake mic through the UI: time runs, stop, the recording is in the list.
    @MainActor
    func testRecordWithFakeMic() throws {
        let mic = Self.fixtures.appending(path: "mic_60s.wav")
        try XCTSkipUnless(FileManager.default.fileExists(atPath: mic.path), "run scripts/dev/make-fixtures.sh")
        let app = XCUIApplication()
        app.launchArguments = ["--reset", "--fake-mic", mic.path, "-AppleLanguages", "(en)"]
        app.launch()
        app.buttons["recordButton"].tap()
        // One-time notice before the first recording.
        let consent = app.alerts.buttons["Understood, record"].firstMatch
        XCTAssertTrue(consent.waitForExistence(timeout: 5))
        consent.tap()
        let elapsed = app.staticTexts["elapsed"]
        XCTAssertTrue(elapsed.waitForExistence(timeout: 5))
        let advanced = NSPredicate(format: "label != '0:00'")
        expectation(for: advanced, evaluatedWith: elapsed)
        waitForExpectations(timeout: 5)
        sleep(2)
        app.buttons["stopButton"].tap()
        let row = app.staticTexts.matching(NSPredicate(format: "label BEGINSWITH 'Recording '")).firstMatch

        // Stopped: the new recording opens by itself. Play (muted: the app mutes playback in
        // automated runs), position advances.
        let position = app.staticTexts["position"]
        XCTAssertTrue(position.waitForExistence(timeout: 10))
        XCTAssertFalse(app.staticTexts["No recordings yet"].exists)
        XCTAssertEqual(position.label, "0:00")
        app.buttons["playButton"].tap()
        expectation(for: NSPredicate(format: "label != '0:00'"), evaluatedWith: position)
        waitForExpectations(timeout: 5)
        app.buttons["playButton"].tap() // pause

        // Rename from the detail screen.
        app.buttons["moreMenu"].tap()
        app.buttons["Rename"].tap()
        let field = app.textFields["titleField"]
        XCTAssertTrue(field.waitForExistence(timeout: 5))
        let clear = String(repeating: XCUIKeyboardKey.delete.rawValue, count: 40)
        field.typeText(clear + "Interview Anna")
        app.buttons["Green"].tap()  // the cassette's colour, in the same sheet
        app.buttons["saveLabel"].tap()
        XCTAssertTrue(app.staticTexts["detailTitle"].waitForExistence(timeout: 5))
        expectation(for: NSPredicate(format: "label == 'Interview Anna'"), evaluatedWith: app.staticTexts["detailTitle"])
        waitForExpectations(timeout: 5)

        // Delete from the detail screen: back in an empty library.
        app.buttons["moreMenu"].tap()
        app.buttons["Delete"].tap()
        let confirm = app.sheets.buttons["Delete"].exists ? app.sheets.buttons["Delete"] : app.buttons.matching(identifier: "Delete").element(boundBy: 0)
        XCTAssertTrue(confirm.waitForExistence(timeout: 5))
        confirm.tap()
        XCTAssertTrue(app.staticTexts["No recordings yet"].waitForExistence(timeout: 10))

        // The notice is shown only once: the next recording starts right away.
        app.buttons["recordButton"].tap()
        XCTAssertTrue(app.staticTexts["elapsed"].waitForExistence(timeout: 5))
        XCTAssertFalse(app.alerts.firstMatch.exists)
        app.buttons["stopButton"].tap()
        XCTAssertTrue(app.staticTexts["position"].waitForExistence(timeout: 10))
        XCTAssertTrue(row.waitForExistence(timeout: 5))
    }

    /// About: settings persist, attribution and licences are shown, the three links are there.
    @MainActor
    func testAboutScreen() {
        let app = XCUIApplication()
        app.launchArguments = ["--reset", "-AppleLanguages", "(en)"]
        app.launch()
        app.buttons["aboutButton"].tap()
        let toggle = app.switches["autoTranscribeToggle"]
        XCTAssertTrue(toggle.waitForExistence(timeout: 5))
        let before = toggle.value as? String
        toggle.switches.firstMatch.tap()
        XCTAssertNotEqual(toggle.value as? String, before)
        let attribution = app.staticTexts["Speech recognition (Voz) and speaker recognition (Who) by Desert Ant Labs (https://desertant.com)"]
        for _ in 0..<8 where !attribution.isHittable { app.swipeUp() }
        XCTAssertTrue(attribution.exists)
        XCTAssertTrue(app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'NVIDIA Parakeet TDT 0.6B v3' AND label CONTAINS 'CC BY 4.0'")).firstMatch.exists)
        let who = app.staticTexts.matching(NSPredicate(format: "label CONTAINS 'pyannote community-1'")).firstMatch
        for _ in 0..<3 where !who.exists { app.swipeUp() }
        XCTAssertTrue(who.exists)
        for _ in 0..<4 where !(app.buttons["neurendal.com"].exists || app.links["neurendal.com"].exists) { app.swipeUp() }
        for link in ["Questions and support", "band.je", "neurendal.com"] {
            XCTAssertTrue(app.buttons[link].exists || app.links[link].exists, link)
        }
        app.buttons["aboutDone"].tap()
        // Restore the default (off) so other runs are not affected.
        app.buttons["aboutButton"].tap()
        XCTAssertTrue(toggle.waitForExistence(timeout: 5))
        XCTAssertNotEqual(toggle.value as? String, before)  // persisted
        toggle.switches.firstMatch.tap()
        XCTAssertEqual(toggle.value as? String, before)
    }
}
